package org.apache.commons.math3.analysis.solvers;

import org.apache.commons.math3.exception.NoBracketingException;
import org.apache.commons.math3.exception.NumberIsTooLargeException;
import org.apache.commons.math3.exception.TooManyEvaluationsException;
import org.apache.commons.math3.util.FastMath;

/**
 * This class implements the <a href="http://mathworld.wolfram.com/MullersMethod.html">
 * Muller's Method</a> for root finding of real univariate functions. For
 * reference, see <b>Elementary Numerical Analysis</b>, ISBN 0070124477,
 * chapter 3.
 * <p>
 * Muller's method applies to both real and complex functions, but here we
 * restrict ourselves to real functions.
 * This class differs from {@link MullerSolver} in the way it avoids complex
 * operations.</p>
 * Except for the initial [min, max], it does not require bracketing
 * condition, e.g. f(x0), f(x1), f(x2) can have the same sign. If complex
 * number arises in the computation, we simply use its modulus as real
 * approximation.</p>
 * <p>
 * Because the interval may not be bracketing, bisection alternative is
 * not applicable here. However in practice our treatment usually works
 * well, especially near real zeroes where the imaginary part of complex
 * approximation is often negligible.</p>
 * <p>
 * The formulas here do not use divided differences directly.</p>
 *
 * @version $Id$
 * @since 1.2
 * @see MullerSolver
 */
public class MullerSolver2 extends AbstractUnivariateSolver {

    /** Default absolute accuracy. */
    private static final double DEFAULT_ABSOLUTE_ACCURACY = 1e-6;

    /**
     * Construct a solver with default accuracy (1e-6).
     */
    public MullerSolver2() {
        this(DEFAULT_ABSOLUTE_ACCURACY);
    }

    /**
     * Construct a solver.
     *
     * @param absoluteAccuracy Absolute accuracy.
     */
    public MullerSolver2(double absoluteAccuracy) {
        super(absoluteAccuracy);
    }

    /**
     * Construct a solver.
     *
     * @param relativeAccuracy Relative accuracy.
     * @param absoluteAccuracy Absolute accuracy.
     */
    public MullerSolver2(double relativeAccuracy,
                        double absoluteAccuracy) {
        super(relativeAccuracy, absoluteAccuracy);
    }

    /**
     * {@inheritDoc}
     */
    @Override
    protected double doSolve()
        throws TooManyEvaluationsException,
               NumberIsTooLargeException,
               NoBracketingException {
        final double min = getMin();
        final double max = getMax();

        verifyInterval(min, max);

        final double relativeAccuracy = getRelativeAccuracy();
        final double absoluteAccuracy = getAbsoluteAccuracy();
        final double functionValueAccuracy = getFunctionValueAccuracy();

        // x2 is the last root approximation
        // x is the new approximation and new x2 for next round
        // x0 < x1 < x2 does not hold here

        double x0 = min;
        double y0 = computeObjectiveValue(x0);
        if (FastMath.abs(y0) < functionValueAccuracy) {
            return x0;
        }
        double x1 = max;
        double y1 = computeObjectiveValue(x1);
        if (FastMath.abs(y1) < functionValueAccuracy) {
            return x1;
        }

        verifyBracketing(x0, x1, y0, y1);

        double x2 = 0.5 * (x0 + x1);
        double y2 = computeObjectiveValue(x2);

        double oldx = Double.POSITIVE_INFINITY;
        while (true) {
            // quadratic interpolation through x0, x1, x2
            final double q = (x2 - x1) / (x1 - x0);
            final double a = q * (y2 - (1 + q) * y1 + q * y0);
            final double b = (2 * q + 1) * y2 - (1 + q) * (1 + q) * y1 + q * q * y0;
            final double c = (1 + q) * y2;
            final double delta = b * b - 4 * a * c;

            final double denominator = computeDenominator(b, delta);
            double x;
            if (denominator != 0) {
                x = computeNextX(x1, x2, c, denominator, absoluteAccuracy);
            } else { 
                x = getRandomX(min, max);
                oldx = Double.POSITIVE_INFINITY;
            }
            final double y = computeObjectiveValue(x);

            // check for convergence
            if (isConverged(x, oldx, y, relativeAccuracy, absoluteAccuracy, functionValueAccuracy)) {
                return x;
            }

            // prepare the next iteration
            x0 = x1;
            y0 = y1;
            x1 = x2;
            y1 = y2;
            x2 = x;
            y2 = y;
            oldx = x;
        }
    }

    /**
     * Verifies that the initial interval bounds bracket a root.
     *
     * @param x0 Minimum bound.
     * @param x1 Maximum bound.
     * @param y0 Function value at minimum bound.
     * @param y1 Function value at maximum bound.
     * @throws NoBracketingException if bounds do not bracket a root.
     */
    private void verifyBracketing(double x0, double x1, double y0, double y1)
        throws NoBracketingException {
        if (y0 * y1 > 0) {
            throw new NoBracketingException(x0, x1, y0, y1);
        }
    }

    /**
     * Computes the denominator for Muller's method update.
     *
     * @param b Coefficient b of the quadratic equation.
     * @param delta Discriminant of the quadratic equation.
     * @return The denominator with the larger magnitude or modulus.
     */
    private double computeDenominator(double b, double delta) {
        if (delta >= 0.0) {
            // choose a denominator larger in magnitude
            double dplus = b + FastMath.sqrt(delta);
            double dminus = b - FastMath.sqrt(delta);
            return FastMath.abs(dplus) > FastMath.abs(dminus) ? dplus : dminus;
        } else {
            // take the modulus of (B +/- FastMath.sqrt(delta))
            return FastMath.sqrt(b * b - delta);
        }
    }

    /**
     * Computes the next root approximation, perturbing it if necessary.
     *
     * @param x1 Previous root approximation.
     * @param x2 Last root approximation.
     * @param c Coefficient c.
     * @param denominator Denominator value.
     * @param absoluteAccuracy Absolute accuracy for perturbation.
     * @return The perturbed next root approximation.
     */
    private double computeNextX(double x1, double x2, double c, double denominator, double absoluteAccuracy) {
        double x = x2 - 2.0 * c * (x2 - x1) / denominator;
        // perturb x if it exactly coincides with x1 or x2
        // the equality tests here are intentional
        while (x == x1 || x == x2) {
            x += absoluteAccuracy;
        }
        return x;
    }

    /**
     * Generates a random value within the [min, max] interval.
     *
     * @param min Minimum bound.
     * @param max Maximum bound.
     * @return A random value within the interval.
     */
    private double getRandomX(double min, double max) { 
        return min + FastMath.random() * (max - min);
    }

    /**
     * Checks if the algorithm has converged.
     *
     * @param x Current approximation.
     * @param oldx Previous approximation.
     * @param y Function value at current approximation.
     * @param relativeAccuracy Relative accuracy tolerance.
     * @param absoluteAccuracy Absolute accuracy tolerance.
     * @param functionValueAccuracy Function value accuracy tolerance.
     * @return True if convergence is achieved, false otherwise.
     */
    private boolean isConverged(double x, double oldx, double y,
                                double relativeAccuracy, double absoluteAccuracy,
                                double functionValueAccuracy) {
        final double tolerance = FastMath.max(relativeAccuracy * FastMath.abs(x), absoluteAccuracy);
        return FastMath.abs(x - oldx) <= tolerance || FastMath.abs(y) <= functionValueAccuracy;
    }
}"
